/* The shared desktop string tables (generated by node tools/i18n/i18n.mjs index desktop; edit the tables, not this file).
 * Loads English and the chosen language from shared/desktop/i18n/<code>/<part>.js; each page that uses shared/desktop/ loads it before its own. */
window.SlopI18n && window.SlopI18n.source({
  ns: 'desktop',
  base: ((document.currentScript || {}).src || '').replace(/[^/]*$/, ''),
  parts: ['main'],
  langs: ['en', 'sv'],
});
